workbox_routing_registerRoute(/^https:\/\/your-api-domain\.com\/.*/, new workbox_strategies_NetworkOnly(), 'GET');
workbox_routing_registerRoute(/^\/_next\/static\/webpack\/.*/, new workbox_strategies_NetworkOnly(), 'GET');
workbox_routing_registerRoute(/^\/_next\/webpack-hmr.*/, new workbox_strategies_NetworkOnly(), 'GET');
workbox_routing_registerRoute(/\.(woff|woff2|ttf|otf)$/, new workbox_strategies_CacheFirst({ "cacheName":"fonts", plugins: [new workbox_expiration_ExpirationPlugin({ maxEntries: 10, maxAgeSeconds: 31536000 }), new workbox_cacheable_response_CacheableResponsePlugin({ statuses: [ 0, 200 ] })] }), 'GET');
workbox_routing_registerRoute(/\.(?:png|jpg|jpeg|svg|gif|css|js)$/, new workbox_strategies_StaleWhileRevalidate({ "cacheName":"static-assets", plugins: [new workbox_expiration_ExpirationPlugin({ maxEntries: 50, maxAgeSeconds: 2592000 })] }), 'GET');
workbox_routing_registerRoute(/.*/, new workbox_strategies_StaleWhileRevalidate({ "cacheName":"html-pages", plugins: [new workbox_expiration_ExpirationPlugin({ maxEntries: 20, maxAgeSeconds: 604800 })] }), 'GET');




